-- Solo lectura. Cada SELECT devuelve una fila (verificacion, resultado); cualquier 'DETENER' indica instalación a revisar.
SELECT 'canecas_secuencias existe' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='canecas_secuencias')=1, 'OK', 'DETENER') AS resultado;
SELECT 'direccion_entrega VARCHAR(500) NULL' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='canecas_ventas' AND COLUMN_NAME='direccion_entrega' AND COLUMN_TYPE='varchar(500)' AND IS_NULLABLE='YES')=1, 'OK', 'DETENER') AS resultado;
-- Informativo: justo tras instalar debe ser 0 (las ventas históricas no se rellenan con direcciones inventadas).
SELECT 'ventas con dirección de entrega' AS verificacion, CAST(COUNT(*) AS CHAR) AS resultado FROM canecas_ventas WHERE direccion_entrega IS NOT NULL;
SELECT 'chk_can_venta_direccion presente' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='canecas_ventas' AND CONSTRAINT_NAME='chk_can_venta_direccion')=1, 'OK', 'DETENER') AS resultado;
SELECT 'activo_unico virtual presente' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='canecas_productos' AND COLUMN_NAME='activo_unico' AND EXTRA LIKE '%VIRTUAL%')=1, 'OK', 'DETENER') AS resultado;
SELECT 'uq_can_producto_activo_unico único sobre (empresa_id,activo_unico)' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='canecas_productos' AND INDEX_NAME='uq_can_producto_activo_unico' AND NON_UNIQUE=0)=2, 'OK', 'DETENER') AS resultado;
SELECT 'trigger de ventas: 2 y el de actualización protege direccion_entrega' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE='canecas_ventas')=2 AND (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='trg_can_venta_bu' AND ACTION_STATEMENT LIKE '%direccion_entrega%')=1, 'OK', 'DETENER') AS resultado;
SELECT 'ninguna empresa con más de una caneca activa' AS verificacion, IF((SELECT COUNT(*) FROM (SELECT empresa_id FROM canecas_productos WHERE activo=1 GROUP BY empresa_id HAVING COUNT(*)>1) t)=0, 'OK', 'DETENER') AS resultado;
SELECT 'recuento canecas_ventas' AS verificacion, CAST(COUNT(*) AS CHAR) AS resultado FROM canecas_ventas;
SELECT 'recuento canecas_productos' AS verificacion, CAST(COUNT(*) AS CHAR) AS resultado FROM canecas_productos;
